import org.jsoup.Connection;
import org.jsoup.helper.HttpConnection;
import org.junit.Test;

import java.io.IOException;
import java.io.InputStream;
import java.net.Proxy;
import java.net.URL;
import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class HttpConnectionTest {

    @Test
    public void connectStringTest() {
        String url = "http://www.test.com";
        Connection connection = HttpConnection.connect(url);
        assertNotNull(connection);
    }

    @Test
    public void connectURLTest() throws Exception {
        URL url = new URL("http://www.test.com");
        Connection connection = HttpConnection.connect(url);
        assertNotNull(connection);
    }

    @Test
    public void connectProxyTest() {
        HttpConnection connection = new HttpConnection();
        Proxy proxy = mock(Proxy.class);
        Connection connectionResult = connection.proxy(proxy);
        assertNotNull(connectionResult);
    }

    @Test
    public void connectProxyHostPortTest() {
        HttpConnection connection = new HttpConnection();
        Connection connectionResult = connection.proxy("localhost", 8080);
        assertNotNull(connectionResult);
    }

    @Test
    public void userAgentTest() {
        HttpConnection connection = new HttpConnection();
        Connection connectionResult = connection.userAgent("Mozilla");
        assertNotNull(connectionResult);
    }

    @Test
    public void dataStringStringTest() {
        HttpConnection connection = new HttpConnection();
        Connection connectionResult = connection.data("key", "value");
        assertNotNull(connectionResult);
    }

    @Test
    public void dataMapTest() {
        HttpConnection connection = new HttpConnection();
        Map<String, String> mapData = new HashMap<>();
        mapData.put("key", "value");
        Connection connectionResult = connection.data(mapData);
        assertNotNull(connectionResult);
    }

    @Test
    public void requestTest() {
        HttpConnection connection = new HttpConnection();
        Connection.Request request = connection.request();
        assertNotNull(request);
    }

    @Test
    public void executeTest() throws IOException {
        HttpConnection connection = new HttpConnection();
        Connection.Response response = connection.execute();
        assertNotNull(response);
    }

    @Test
    public void getTest() throws IOException {
        HttpConnection connection = new HttpConnection();
        Document document = connection.get();
        assertNotNull(document);
    }

    @Test
    public void dataWithInputStreamTest() throws Exception {
        String key = "image";
        String filename = "test.jpg";
        InputStream inputStream = mock(InputStream.class);
        HttpConnection connection = new HttpConnection();
        connection.data(key, filename, inputStream);
        // verify if the data has been set - by calling data method again with the key
        assertNotNull(connection.data(key));
    }

    @Test
    public void postTest() throws IOException {
        HttpConnection httpConnection = new HttpConnection();
        Document document = httpConnection.post();
        assertNotNull(document);
    }
}
